import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName, type Persona } from "../../fixtures";
import type { APIRequestContext } from "@playwright/test";

type Doc = { id: string; kind: string; status: string };
type Field = { value: string | null; confidence: number };
type Extraction = { fields: Record<string, Field> };
type QueueItem = { vendor_id: string; lowest_confidence: number; extractions: Extraction[] };

const UPLOADS: Array<[string, string]> = [
  ["w9", "w9.txt"],
  ["insurance_certificate", "insurance_certificate.txt"],
  ["contract", "contract.txt"],
];

async function createSubmittedVendor(member: APIRequestContext, insuranceFile: string): Promise<string> {
  const create = await member.post("/api/vendors", {
    data: { name: uniqueName("Queue"), category: "services", contact_email: "ops@queue.example" },
  });
  expect(create.status(), await create.text()).toBe(201);
  const vendorId = ((await create.json()) as { id: string }).id;

  for (const [kind, file] of UPLOADS) {
    const name = kind === "insurance_certificate" ? insuranceFile : file;
    const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind,
        file: { name, mimeType: "text/plain", buffer: readFileSync(sample(name)) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendorId}/documents`);
        const docs = (await res.json()) as Doc[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 15_000 },
    )
    .toBe(true);

  const submit = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);
  return vendorId;
}

test("the review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange: one vendor with a low-confidence insurance certificate, one with clean documents
  const member = await apiAs("member");
  const lowId = await createSubmittedVendor(member, "insurance_certificate_unparseable.txt");
  const highId = await createSubmittedVendor(member, "insurance_certificate.txt");

  // Act
  const reviewer = await apiAs("reviewer");
  let items: QueueItem[] = [];
  await expect
    .poll(
      async () => {
        const res = await reviewer.get("/api/review-queue");
        expect(res.status(), await res.text()).toBe(200);
        items = (await res.json()) as QueueItem[];
        return [lowId, highId].every((id) => items.some((i) => i.vendor_id === id));
      },
      { timeout: 15_000 },
    )
    .toBe(true);

  // Assert: the queue is sorted by lowest confidence, ascending
  for (let i = 1; i < items.length; i++) {
    expect(items[i].lowest_confidence, `queue order at index ${i}`).toBeGreaterThanOrEqual(
      items[i - 1].lowest_confidence,
    );
  }

  // Assert: each item's lowest confidence is the minimum across its extractions' fields
  for (const item of items) {
    const confidences = item.extractions.flatMap((e) => Object.values(e.fields).map((f) => f.confidence));
    expect(item.lowest_confidence).toBeCloseTo(Math.min(...confidences), 5);
  }

  // Assert: our low-confidence vendor sits ahead of the clean one
  const lowIndex = items.findIndex((i) => i.vendor_id === lowId);
  const highIndex = items.findIndex((i) => i.vendor_id === highId);
  expect(lowIndex).toBeLessThan(highIndex);
});
